// Instantiate with a safe floating type (double) to satisfy template requirements.
// Generate a random double value and compute its absolute value via the target template.
double v = *FUZZ_PARAM(double);
double r = PointMatcherSupport::anyabs<double>(v);

// Property checks:
// 1) For finite, non-NaN inputs: r should equal (v<0?-v:v) within a tiny epsilon.
// 2) For NaN inputs: result should be NaN as well (propagates NaN through unary - and selection).
// 3) Result should be non-negative unless it is NaN.
const double eps = 1e-15;
bool v_is_nan = (v != v);
bool r_is_nan = (r != r);
if (v_is_nan) {
    FUZZ_ASSERT(r_is_nan, "anyabs<double>(NaN) should produce NaN");
} else {
    double expected = (v < 0.0 ? -v : v);
    double diff = (r >= expected ? r - expected : expected - r);
    FUZZ_ASSERT(diff <= eps, "anyabs<double> result deviates from expected abs value");
    FUZZ_ASSERT(r >= 0.0, "anyabs<double> produced a negative result");
}

